import express, { type ErrorRequestHandler } from "express";
import helmet from "helmet";
import { ZodError } from "zod";

import { users } from "./routes/users.js";

/** The app without listening, so tests can drive it with Supertest. */
export function createApp() {
  const app = express();
  app.use(helmet());
  app.use(express.json({ limit: "1mb" }));

  app.get("/health", (_req, res) => {
    res.json({ status: "ok" });
  });
  app.use("/users", users);

  app.use((_req, res) => {
    res.status(404).json({ error: "Not found" });
  });
  app.use(errorHandler);
  return app;
}

/** One place turns errors into responses: validation → 400, the rest → 500 without internals. */
const errorHandler: ErrorRequestHandler = (error, _req, res, _next) => {
  if (error instanceof ZodError) {
    res.status(400).json({ error: "Invalid request", issues: error.issues });
    return;
  }
  console.error(error);
  res.status(500).json({ error: "Internal server error" });
};

import { Router } from "express";
import { z } from "zod";

const newUser = z.object({ name: z.string().min(1), email: z.email() });

export const users = Router();

// Express 5 forwards rejected promises and thrown errors to the error handler.
users.post("/", async (req, res) => {
  const input = newUser.parse(req.body);
  res.status(201).json({ id: crypto.randomUUID(), ...input });
});

import { createApp } from "./app.js";

const port = Number(process.env.PORT ?? 3000);
createApp().listen(port, () => {
  console.log(`Listening on http://localhost:${port}`);
});

import request from "supertest";
import { describe, expect, it } from "vitest";

import { createApp } from "./app.js";

const app = createApp();

describe("api", () => {
  it("answers the health check", async () => {
    const res = await request(app).get("/health");
    expect(res.status).toBe(200);
    expect(res.body).toEqual({ status: "ok" });
  });

  it("creates a user from valid input", async () => {
    const res = await request(app).post("/users").send({ name: "Ada", email: "ada@example.com" });
    expect(res.status).toBe(201);
    expect(res.body).toMatchObject({ name: "Ada", email: "ada@example.com" });
  });

  it("rejects invalid input with 400", async () => {
    const res = await request(app).post("/users").send({ name: "" });
    expect(res.status).toBe(400);
  });
});
